public class TranslateText {

    public static void main(String[] args) {
        String gujaratiText = "નવી એઇમ્સની આસપાસ શોપિંગ સેન્ટર, કેન્ટીન વગેરે જેવી સુવિધાઓ અને સેવાઓ આકાર લેશે, જેથી પરોક્ષ રીતે રોજગારીનું સર્જન પણ થશે.";

