                .endpoint("https://api.microsofttranslator.com")
                .newBuilder()
                .build();

        client.addConsumer(
                new Consumer<TranslationClient>() {
                    @Override
                    public void consume(TranslationClient api) throws Exception {
                        String apiKey = "YOUR_API_KEY";
                        Language sourceLanguage = Language.fromLanguageTag("gu");
                        Language targetLanguage = Language.fromLanguageTag("te");

                        List<TranslationInput> inputs = new ArrayList<>();
                        TranslationInput input = new TranslationInput(gujaratiText, TranslationTextType.PLAIN_TEXT);
