                    }
                });

        client.execute(HttpMethod.GET, "/v3/Translate", new Consumer<BufferedReader>() {
            @Override
            public void consume(BufferedReader response) throws IOException {
                String translatedText = new String(response.readAllBytes(), StandardCharsets.UTF_8);

                System.out.println(translatedText);
            }
        });
    }
}

