import com.github.springtestdbunit.DbUnitTestExecutionListener;
import com.github.springtestdbunit.SpringConfigurableJdbcDatabaseTester;
import com.tngtech.gga.Gauntlets;
import com.tngtech.gga.annotation.BeforeGauntlets;
import org.dbunit.Assertion;
import org.dbunit.dataset.IDataSet;
import org.dbunit.dataset.ComparisonComparisonUnit;
import org.dbunit.dataset.xml.XmlDataSet;
import org.junit.runner.RunWith;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.jdbc.AutoConfigureTestDatabase;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.client.TestRestTemplate;
import org.springframework.context.ApplicationContext;
import org.springframework.test.context.TestExecutionListeners;
import org.springframework.test.context.runner.RunWithClasses;

import java.io.File;

@RunWith(Gauntlets.class)
@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
@TestExecutionListeners(value = {DbUnitTestExecutionListener.class})
@AutoConfigureTestDatabase(replace = AutoConfigureTestDatabase.Replace.NONE)
public class InvoiceGTestSuite {

    private String endpoint = "/api/invoices";

    @Autowired
    private TestRestTemplate testRestTemplate;

    @Autowired
    private ApplicationContext applicationContext;

    @BeforeGauntlets
    public void setup() {
        Gauntlets.beforeGauntlets(() -> {
            SpringConfigurableJdbcDatabaseTester databaseTester = new SpringConfigurableJdbcDatabaseTester(
                    applicationContext.getEnvironment().getProperty("spring.datasource.url"),
                    applicationContext.getEnvironment().getProperty("spring.datasource.username"),
                    applicationContext.getEnvironment().getProperty("spring.datasource.password")
            );

            // Carga del dataset de prueba
            File xmlDataSetFile = new File("src/test/resources/dbunit/invoices.xml");
            IDataSet expectedDataSet = new XmlDataSet(xmlDataSetFile);

            databaseTester.setDataSet(expectedDataSet);
            databaseTester.onSetup();
        });
    }

    @RunWithClasses(value = InvoiceTestCases.class)
}
```

