      accessorInfos.push(gl.createBuffer());
      gl.bindBuffer(bufferTarget, accessorInfos[accessorInfoIndex]);
      gl.bufferData(bufferTarget, accessor.byteLength, WebGLRenderingContext.DYNAMIC_DRAW);
      gl.bufferSubData(
        bufferTarget,
        accessor.byteOffset,
        new Uint8Array(accessor.count * accessor.componentType, accessor.buffer, accessor.byteOffset)
      );
      gltf.uploadBuffer(accessor, accessor.byteOffset, accessor.byteLength);
    });

    gltf.finalize();

    return gltf;
  }

  return new GLTFLoader();
})();
```

