        // Entrada del usuario
        Console.Write("¿Cuál sentimiento estás considerando? ");
        string input = Console.ReadLine();

        // Sentimientos y sus correspondientes labels
        Dictionary<string, string> sentimientos = new Dictionary<string, string>() {
