        cam.setVideoResolution(VGA);
    }
    catch (AxisException& e) {
        cerr << "Error al cambiar la configuración de vídeo: " << e.what() << endl;
    }
}

// Dispara una alarmas entradas de la cámara
void triggerAlarm(IPCamera& cam)
{
    try {
        cam.setEventTrigger(EventTypes::ALARM);
        cam.setEventSource(AlarmSources::FOOT_FACT);
        cam.setEventPending(false);
        cam.createEventNotification(NotifyTypes::E_MAIL, "user@example.com");
    }
    catch (AxisException& e) {
        cerr << "Error al disparar alarmas: " << e.what() << endl;
    }
}

