            return [];
          }

          return ctx.parentPath.findParent(path => path.isCallExpression()).get("arguments").some(arg => {
            const identifierNode = arg.node;

            if (
              identifierNode.type === "Identifier" &&
              (identifierNode.name === "$data" || identifierNode.type === "MemberExpression" && identifierNode.object.type === "ThisExpression" && identifierNode.property.type === "Identifier") &&
              arg.parentPath.parentPath.node.body.some(node => {
                if (node.type === "ExpressionStatement" && node.expression.type === "AssignmentExpression") {
                  const left = node.expression.left;
                  const right = node.expression.right;

