      meta: {
        type: 'rule',
        docs: {
          description:
            'Enforce avoiding modifying internal state within updated lifecycle hook and discourage calling methods that modify state',
          category: 'Best Practices',
          recommended: true,
        },
        fixable: 'code',
        schema: [],
      },

