          const methods = object.fromEntries(
            updatedHookBody.body.filter(
              (item) =>
                item.type === 'MethodDefinition' &&
                item.key.name === 'updated'
            ).reduce((acc, curr) => ({
              ...acc,
              [curr.value.id.name]: curr,
            }), {}),
          );

