                    );
                  },
                });
              }
            }
          }
        }

        function checkMethodCall(path, method) {
          const { callee } {
            checkModifierMethod(callee, true); // Analiza la función llamada
          }
        }

        function checkModifiers(node) {
          // Recorre el cuerpo del hook actualizado y analiza cada método definido
          node.body.forEach((item) => {
            if (item.type === 'MethodDefinition') {
              const { key: methodName, value } = item;
