                      expression.type === 'CallExpression' &&
                      expression.callee.object &&
                      expression.callee.object.name === 'this' &&
                      expression.callee.property &&
                      expression.callee.properties.length === 1 &&
                      expression.callee.properties[0].key.name === dataProp
