                        checkModifierMethod(left, true);

                        // Para métodos llamados dentro del método
                        value.body.forEach((innerBodyStatement) => {
                          if (innerBodyStatement.type === 'ExpressionStatement') {
                            checkMethodCall(innerBodyStatement.expression, methodName.value);
                          }
                        });
                      });
                    }
                  }
                });
              }
            }
          });
