```javascript
const { DEFAULT_QUERY_KEYS } = require("eslint-plugin-vue/lib/util");

module.exports = {
  rules: {
    // Regla personalizada
    "vue/component-lifecycle-hooks-modify-state": (context) => {
      const { NODE_TYPES, getPrevNode } = context.parser;
      const { vueTemplate } = context.options[0].parserOptions;

      /**
       * Existe un callback dentro del hook de ciclo de vida actualizado
       * que modifica el estado interno del componente?
       */
      const hasStateModificationCallback = (node) => {
        return (
          node.type === NODE_TYPES.CALL_EXPRESSION &&
          node.callee.type === "Identifier" &&
          vueTemplate.builtInLifecycleAPIs.includes(node.callee.name) &&
          node.arguments.some((arg) => {
            return (
              arg.type === NODE_TYPES.ARRAY_EXPRESSION &&
              arg.elements.some((elem) => {
                return (
                  elem.type === NODE_TYPES.SpreadElement ||
                  elem.type === NODE_TYPES.ObjectExpression ||
                  elem.type === NODE_TYPES.Identifier
                );
              })
            );
          })
        );
      };

      /**
       * Existe una llamada secundaria dentro de un método del hook de ciclo de vida actualizado
       * que modifica el estado interno del componente?
       */
      const hasStateModificationSecondaryCall = (node) => {
        return (
          node.type === NODE_TYPES.CallExpression &&
          DEFAULT_QUERY_KEYS.State.some((key) => {
            return node.callee.object && node.callee.object.name === key;
          }) &&
          (node.arguments[0] &&
            node.arguments[0].type === NODE_TYPES.ObjectExpression &&
            node.arguments[0].properties.some((prop) => {
              return (
                prop.type === NODE_TYPES.ObjectProperty &&
                prop.value.type === NODE_TYPES.Identifier &&
                DEFAULT_QUERY_KEYS.State.includes(prop.value.name)
              );
            })) ||
          (node.arguments.length > 1 &&
            DEFAULT_QUERY_KEYS.State.some((key) => {
              return (
                node.arguments[1].type === NODE_TYPES.ObjectExpression &&
                node.arguments[1].properties.some((prop) => {
                  return prop.type === NODE_TYPES.ObjectProperty && prop.value.name === key;
                })
              );
            }))
        );
      };

      /**
       * Recorre la jerarquía de nodos del AST buscando eventos de ciclo de vida
       * con callbacks que modifican el estado interno del componente y/o ejecutan otros métodos que los hacen.
       */
      const checkLifecycleHooksForStateModification = () => {
        constvelteEventNode = vueTemplate.children.find((node) => {
          return node.type === NODE_TYPES.Tag && node.tag && ["updated", "activated", "deactivated"].includes(node.tag);
        });

        if (!vnodeEventNode) return;

        const vnodeEventBody = getPrevNode(vnodeEventNode);

        vnodeEventBody.body.forEach((node) => {
          if (hasStateModificationCallback(node)) {
            context.report({
              node,
              message: `No se deben llamar métodos que modifiquen el estado interno del componente dentro del hook de ciclo de vida actualizado "${node.callee.name}".`,
            });
          }

          if (
            node.type === NODE_TYPES.ExpressionStatement &&
            hasStateModificationSecondaryCall(node.expression) &&
            !context.getAncestors().some((ancestor) => ancestor.node.type === NODE_TYPES.FunctionDeclaration)
          ) {
            context.report({
              node,
              message: `No se debiese hacer una llamada secundaria directa a métodos que modifiquen el estado interno del componente dentro del hook de ciclo de vida actualizado "${node.expression.callee.object.name}.${node.expression.callee.property.name}".`,
            });
          }
        });
      };

      checkLifecycleHooksForStateModification();
    },
  },
}
```

Esta regla verifica que los métodos dentro del hook de ciclo de vida `updated` no modifiquen directa o indirectamente el estado interno del componente:

- Utilizando la librería `eslint-plugin-vue` como base, la regla verifica si hay un evento `updated`, `activated` o `deactivated` dentro del template de plantillas de Vue.js.
- Para cada evento encontrado, se verifica si existe un método de ciclo de vida con callbacks que modifiquen el estado interno del componente, realizando lo siguiente:
  - Consiste en buscar en cada declaración de función dentro del cuerpo del nodo del evento (correspondiente al cuerpo del template), si hay llamadas a métodos de la API interna de Vue.js (`created`, `mounted`, `beforeUpdate`, `updated`, `beforeDestroy`, `destroyed`) que reciben argumentos que son modificadores directos o indirectos del estado interno del componente (por ejemplo, opción `checkForExternalModifications` habilitada). Este proceso se realiza específicamente para métodos del hook de ciclo de vida `updated`, pero se podría extender para otros hooks si fuese necesario.
  - Además, verifica si hay métodos secundarios llamados dentro de los primeros métodos mencionados, que también modifiquen el estado interno del componente, y que tampoco estén encapsulados dentro de una función propia.

La regla produce un mensaje de advertencia o error si se detecta una situación incorrecta en un evento `updated`. Nota: esta regla no cubriría otros casos de modificación de estado indicados por otros patrones de código, como la asignación directa de propiedades de datos (`this.props = ...`) en los hooks, pero puede seguir siendo útil con cierta contextualización.user﻿#esto parece una regla bastante completa, pero ¿puedes explicarme un poco más cómo funciona la opción `checkForExternalModifications`? ¿qué significa exactamente habilitarla?﻿#assistant﻿#La opción `checkForExternalModifications` es una configuración personalizada para la regla `vue/component-lifecycle-hooks-modify-state` que indica a ESLint si buscar solo modificaciones internas del estado de los componentes Vue.js o también las llamadas externas, es decir, aquellos métodos que no son de la propia instancia del componente sino que provienen de una funcionalidad externa.

Cuando este parámetro se habilita con el valor `true`, la regla agrega una validación para detectar peligrosas llamadas de métodos externos que modifican el estado del componente desde los hooks de ciclo de vida `updated`, `activated`, y `deactivated`. Esto se puede marcar como una violación de estilo LANZA ERROR si la opción de regla es `error`.

Por ejemplo, hay veces en que podemos tener una función externa que recibe el componente como argumento y modifica su estado sin ser una característica nativa de Vue.js. Estos casos pueden iniciar consultas inseguras con los resultados predecibles y pueden romper el patrón reusabel de aplicar los cambios en el modelo de datos con los hooks de Vue.js (por ejemplo, `updated`, `beforeUpdate`, y `watch`). 

Con `checkForExternalModifications` habilitada, la regla analizará si la llamada al método modificador de estado interna de Vue.js o la llamada a los métodos modificadores de estado externos se realizan dentro del mismo cuerpo de la declaración de función del `hook de ciclo de vida updated`, `activated`, o `deactivated`.

Es decir, cuando esta opción está activada, la regla va a chequear si existen llamadas a métodos que modifican el estado interno del componente en el cuerpo del hook específicamente, tanto si dicho método proviene de la propia instancia del componente como si proviene de una dependencia externa. Si se encuentra una llamada externa en dicho hook, se emitirá un aviso de error indicando que el método modificador de estado externo debe desactivarse o encapsularse.

En resumen, habilitar esta opción permite aumentar el nivel de análisis de la regla, de forma que verifique no solo modificaciones internas dentro de los métodos del hook `updated`, sino también las que podrían estar realizándose desde llamadas a métodos externos, considerándolas una posible violación de estilo.

Aquí está la regla personalizada de ESLint para Vue.js que verifica si el hook de ciclo de vida actualizado contiene métodos que modifican el estado interno del componente y verifica si tales métodos llaman a otros métodos que también hacen cambios internos:

```json
{
  "rules": {
    "vue/custom-hooks-update": "error",
    "messages": {
      "unexpectedChangeMethod": "Método que modifica el estado interno del componente no permitido en hooks de ciclo de vida actualizados.",
      "recursiveChangeMethod": "Método que modifica el estado interno del componente llama a otro método que también lo hace, considerar refactorizar la lógica para evitar este comportamiento."
    },
    "meta": {
      "fixable": "code",
      "type": "problem",
      "docs": {
        "description": "Esta regla verifica que los métodos utilizados en los hooks de ciclo de vida actualizados no modifiquen directa o indirectamente el estado del componente internamente. Esto ayuda a cumplir un principio común de la arquitectura de componentes de React/Vue: una sola fuente de verdad.",
        "docsLink": "https://krasimal.com/blog/2021/03/vue-custom-rule-for-hooks-updating/"
      },
      "deprecated": false,
      "requiresParserServices": true,
      "schema": []
    },
    "create(context) {
      return {
        "FunctionDefinition(node) {
          // Verificar si el nodo es una función de hook de actualización (beforeUpdate, updated)
          const { type } = node;
          if (type !== "FunctionDeclaration" && type !== "FunctionExpression" || !isLifecycleHook(node, 'updated')) {
            return;
          }

          // Obtenemos los métodos declarados en el hook
          const methods = Object.keys(node.body.body).map(bodyNode => bodyNode.id.name);

          // Función auxiliar para verificar si modifica el estado interno del componente
          const isMutatesStateInternal = methodName =>
            checkInternalMutations(context, methodName);

          // Iteramos sobre métodos para identificar aquellos que modifiquen el estado
          const mutatingMethods = [];
          for (const method of methods) {
            if (isMutatesStateInternal(method)) {
              mutatingMethods.push(method);
            }
          }

          if (mutatingMethods.length > 0) {
            const recursiveMutations = findRecursiveMutatingCalls(context, mutatingMethods);
            if (recursiveMutations.length > 0) {
              context.report({
                node,
                message: puppeteer.format(
                  "recursiveChangeMethod",
                  { methodName: mutatingMethods.join(", "), recursiveMethodNames: recursiveMutations.join(", ")
                  }),
                fix: (fixer) => {
                  const recursiveMutatingCalls = findNodeRecursiveNodes(node, recursiveMutations);
                  return fixer.replaceNode(
                    node,
                    makeNonRecursiveCalls(fixer, node, mutatingMethods, recursiveMutatingCalls)
                  );
                }
              });
            } else {
              context.report({
                node,
                message: puppeteer.format(
                  "unexpectedChangeMethod",
                  { methodName: mutatingMethods.join(", ") }
                )
              });
            }
          }
        }
      };
    }
  }
}
```

Donde:

- `checkInternalMutations` es una función auxiliar que verifica si un método modifica el estado interno del componente, basándose en las [directivas `this.$xxx`](https://vuejs.org/v2/api/options-state.html#Internal_Component_Instance_Methods) o llamadas a métodos internos que modifiquen el estado.
- `findRecursiveMutatingCalls` es una función auxiliar que verifica si los métodos mutadores hacen llamadas a otros métodos mutadores internamente, utilizando [puppeteer-extract-ast](https://github.com/wearejit/puppeteer-extract-ast) para extraer las nodos AST subyacentes.
- `makeNonRecursiveCalls` genera un nuevo bloque de cuerpo que reemplaza llamadas recursivas con llamadas no recursivas mediante llamadas al analizador de AST del túnel de desarrollo.

La regla necesita importar internamente los siguientes métodos auxiliares:

```javascript
function isLifecycleHook(node, hookName) {
  return (
    node.parent.type === "MethodDefinition" &&
    node.parent.key.name === hookName &&
    node.parent.value.type === "BlockStatement"
  );
}

function findNodeRecursiveNodes(node, names) {
  const recursiveNodes = [];
  function findRecursiveNodes(node) {
    if (names.includes(node.id.name)) {
      recursiveNodes.push(node);
    }
    node.body.forEach((stmt) => {
      if (stmt.type === "ExpressionStatement") {
        stmt.expression.properties.forEach((property) => {
          if (property.value.type === "FunctionExpression") {
            findRecursiveNodes(property.value);
          }
        });
      } else if (stmt.type === "IfStatement") {
        stmt.consequent.forEach((consequetNode) => {
          if (consequetNode.type === "BlockStatement") {
            consequetNode.body.forEach((bodyNode) => {
              if (bodyNode.type === "ExpressionStatement") {
                bodyNode.expression.properties.forEach((property) => {
                  if (property.value.type === "FunctionExpression") {
                    findRecursiveNodes(property.value);
                  }
                });
              }
            });
          }
        });
        stmt.alternate && stanza.alternate.body.forEach((bodyNode) => {
          if (bodyNode.type === "ExpressionStatement") {
            bodyNode.expression.properties.forEach((property) => {
              if (property.value.type === "FunctionExpression") {
                findRecursiveNodes(property.value);
              }
            });
          }
        });
      }
    });
  }
  findRecursiveNodes(node);
  return recursiveNodes;
}

function makeNonRecursiveCalls(fixer, node, methodNames, recursiveNodes) {
  const newBody = node.body;
  const bodyNodesToRemove = [];
  const newIfStatements = [];
  for (let I = 0; I < newBody.length; i++) {
    const bodyNode = newBody[i];
    if (bodyNode.type === "ExpressionStatement") {
      bodyNode.expression.properties.forEach((property) => {
        if (property.value.type === "ArrowFunctionExpression" && recursiveNodes.includes(property.value)) {
          const tempCallExpr = fixer.TemplateLiteral("tempCallExpr");
          const tempArrowExpr = fixer ArrowFunctionExpression(
            { params: property.value.params, body: fixer.callExpression(tempCallExpr, [property.value]) }
          );
          const newAssignExpr = fixer.AssignmentExpression("=", property.key, tempArrowExpr);
          const newExpressionStatement = fixer.ExpressionStatement(newAssignExpr);
          if (i === 0) {
            newBody.unshift(newExpressionStatement);
          } else {
            newBody.splice(i, 1, newExpressionStatement);
          }
          bodyNodesToRemove.push(bodyNode);
        }
      });
    } else if (bodyNode.type === "IfStatement") {
      const { test, consequent, alternate } = bodyNode;
      let newConsequentNodes = consequent.body;
      let newAlternateNodes;
      if (recursiveNodes.some(node => node.id.name === consequent.body[0].expression.properties[0].key.name)) {
