        const tempArrowExpr = fixer ArrowFunctionExpression({
          params: consequent.body[0].expression.properties[0].value.params,
          body: fixer.callExpression(tempCallExpr, [consequent.body[0].expression.properties[0].value])
        });
        const newAssignExpr = fixer.AssignmentExpression(
          "=",
          consequent.body[0].expression.properties[0].key,
          tempArrowExpr
        );
        const newExpressionStatement = fixer.ExpressionStatement(newAssignExpr);
        newConsequentNodes = [newExpressionStatement, ...consequent.body.slice(1)];
      } else {
        newConsequentNodes = consequent.body;
      }
      if (alternate) {
        newAlternateNodes = alternate.body.map(bodyNode => {
          return fixer.visit(bodyNode, (node) => {
            if (node.type === "ExpressionStatement") {
              node.expression.properties.forEach((property) => {
                if (property.value.type === "ArrowFunctionExpression" && recursiveNodes.includes(property.value)) {
                  const tempCallExpr = fixer.TemplateLiteral("tempCallExpr");
                  const tempArrowExpr = fixer ArrowFunctionExpression({
                    params: property.value.params,
                    body: fixer.callExpression(tempCallExpr, [property.value])
                  });
                  const newAssignExpr = fixer.AssignmentExpression(
                    "=",
                    property.key,
                    tempArrowExpr
                  );
                  const newExpressionStatement = fixer.ExpressionStatement(newAssignExpr);
                  bodyNodesToRemove.push(node);
