          },
          test: fixer.logicalExpression("||", test, fixer.identifier("false")),
          consequent: fixer.blockStatement(newConsequentNodes),
          alternate: alternate ? fixer.blockStatement(newAlternateNodes) : null
        })
      );
      bodyNodesToRemove.push(bodyNode);
    }
  }
  newBody.splice(
    ...bodyNodesToRemove.map((node, index) => [index, 1])
  );
  // Regenerar nuevo bloque con instrucciones IF necesarias para sin recursión.
  return fixer.replaceNode(node, fixer.blockStatement([
    ...newIfStatements,
    ...newBody
